package com.shazwan.idash3;
import android.media.*;import android.media.session.*;import android.net.Uri;import android.os.*;import java.util.*;import java.util.concurrent.*;
/** Foreground panel player: one decoder, one bounded queue, no background service or frame polling. */
final class NativeMusicEngine implements AutoCloseable {
 final LauncherActivity a;final MediaSession session;final java.util.List<MusicTrack> queue=new ArrayList<>();final ExecutorService worker=Executors.newSingleThreadExecutor();final AudioManager audio;final AudioFocusRequest focus;
 MediaPlayer player;BitChordCatalogue resolving;Future<?> job;Runnable changed;int index=-1,generation;boolean prepared,closed,playing;String state="Cari lagu atau pilih fail audio";
 NativeMusicEngine(LauncherActivity host){a=host;audio=(AudioManager)a.getSystemService(android.content.Context.AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(value->{if(value<0)pause();},a.main).build();session=new MediaSession(a,"iDash BitChord Native");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onPlay(){resume();}public void onPause(){pause();}public void onSkipToNext(){step(1);}public void onSkipToPrevious(){step(-1);}public void onSeekTo(long p){seek((int)p);}public void onStop(){pause();}},a.main);session.setActive(true);a.nativeMusic=this;}
 MusicTrack current(){return index>=0&&index<queue.size()?queue.get(index):null;}
 void notifyUi(){MusicTrack t=current();if(t!=null)session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,t.title).putString(MediaMetadata.METADATA_KEY_ARTIST,t.artist).putString(MediaMetadata.METADATA_KEY_ALBUM,t.album).putLong(MediaMetadata.METADATA_KEY_DURATION,duration()).build());long actions=PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SEEK_TO;if(index>0)actions|=PlaybackState.ACTION_SKIP_TO_PREVIOUS;if(index+1<queue.size())actions|=PlaybackState.ACTION_SKIP_TO_NEXT;session.setPlaybackState(new PlaybackState.Builder().setActions(actions).setState(playing?PlaybackState.STATE_PLAYING:prepared?PlaybackState.STATE_PAUSED:current()==null?PlaybackState.STATE_NONE:state.startsWith("Ralat")?PlaybackState.STATE_ERROR:PlaybackState.STATE_BUFFERING,position(),playing?1:0).build());if(a.driveDashboard!=null&&a.driveDashboard.media.active&&!a.driveDashboard.media.ownsNative())a.driveDashboard.media.reload();if(changed!=null)changed.run();}
 void play(List<MusicTrack> songs,int at){if(closed||songs.isEmpty()||at<0||at>=songs.size())return;queue.clear();queue.addAll(songs.subList(0,Math.min(50,songs.size())));index=Math.min(at,queue.size()-1);load();}
 void cancel(){generation++;if(job!=null)job.cancel(true);if(resolving!=null)resolving.close();resolving=null;if(player!=null){player.release();player=null;}prepared=false;playing=false;audio.abandonAudioFocusRequest(focus);}
 void load(){cancel();MusicTrack t=current();if(t==null)return;int ticket=generation;state="Memuat audio…";notifyUi();resolving=new BitChordCatalogue();BitChordCatalogue client=resolving;job=worker.submit(()->{try{String url=client.resolve(t);a.main.post(()->{if(!closed&&ticket==generation)prepare(url,t.local);});}catch(Exception failure){a.main.post(()->{if(!closed&&ticket==generation){state="Ralat: "+failure.getMessage();notifyUi();}});}});}
 void prepare(String location,boolean local){try{MediaPlayer p=new MediaPlayer();player=p;p.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());p.setOnPreparedListener(mp->{if(closed||player!=mp)return;prepared=true;resume();});p.setOnCompletionListener(mp->{if(player!=mp||closed)return;if(index+1<queue.size())step(1);else{playing=false;state="Tamat giliran";audio.abandonAudioFocusRequest(focus);notifyUi();}});p.setOnErrorListener((mp,what,extra)->{if(player==mp){prepared=false;playing=false;state="Ralat audio ("+what+"/"+extra+")";mp.release();player=null;audio.abandonAudioFocusRequest(focus);notifyUi();}return true;});if(local){try(ParcelFileDescriptor fd=a.getContentResolver().openFileDescriptor(Uri.parse(location),"r")){if(fd==null)throw new java.io.IOException("Fail tidak tersedia");p.setDataSource(fd.getFileDescriptor());}}else p.setDataSource(location);p.prepareAsync();}catch(Exception failure){if(player!=null){player.release();player=null;}state="Ralat: "+failure.getMessage();notifyUi();}}
 void resume(){if(closed)return;if(!prepared){if(current()!=null&&player==null)load();return;}if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){state="Audio sedang digunakan app lain";notifyUi();return;}try{player.start();playing=true;state="Sedang dimainkan";}catch(IllegalStateException e){state="Ralat audio";}notifyUi();}
 void pause(){if(closed)return;if(playing&&player!=null)try{player.pause();}catch(IllegalStateException ignored){}playing=false;audio.abandonAudioFocusRequest(focus);if(prepared)state="Dijeda";else if(current()!=null){cancel();state="Dijeda · tekan Play untuk cuba semula";}notifyUi();}
 void toggle(){if(playing)pause();else resume();}
 void step(int by){int next=index+by;if(next>=0&&next<queue.size()){index=next;load();}}
 int position(){try{return prepared&&player!=null?player.getCurrentPosition():0;}catch(IllegalStateException e){return 0;}}
 int duration(){try{return prepared&&player!=null?player.getDuration():0;}catch(IllegalStateException e){return 0;}}
 void seek(int p){if(prepared&&player!=null)player.seekTo(Math.max(0,Math.min(duration(),p)));notifyUi();}
 public void close(){if(closed)return;cancel();closed=true;changed=null;worker.shutdownNow();session.setActive(false);session.release();if(a.nativeMusic==this)a.nativeMusic=null;}
}
